INSERT INTO found_bug
(id,title,severity,category,ddl_op,feature,symptom,repro,expected,actual,root_cause,fix_hint,oracle,method,root_cause_id,affects,confirmed,status,notes)
VALUES
(1800003,'Cancelled ALTER TABLE PLACEMENT silently applies the uncommitted replica rule in PD','high','ddl_control_plane','ALTER TABLE ... PLACEMENT POLICY','placement rules','Cancelled DDL retains the old placement policy in TiDB metadata while PD schedules the new uncommitted voter count.','Create p1 FOLLOWERS=2 and p2 FOLLOWERS=1, create a nonpartition table with p1, pause after PutRuleBundles succeeds, run ALTER TABLE ... p2, ADMIN CANCEL the job, release it, then compare SHOW CREATE and PD group TiDB_DDL_<table_id>.','Cancellation leaves both metadata and PD on p1 with three voters.','ALTER returns 8214 and history is cancelled; SHOW CREATE remains p1, but PD retains p2 with two voters.','onAlterTablePlacement publishes the new PD bundle before the DDL transaction/job is durable, and generic cancellation has no compensation edge.','Publish through a durable intent/reconciler or restore the committed metadata bundle on every later abort edge.','ddl-terminal-metadata-pd-bundle-coherence','current-source-proof-obligation-plus-local-and-real-pd-matrix','table-placement-pd-bundle-before-ddl-commit','master 13282a8bd06b',1,'confirmed','Independent local mock-PD and authorized testbed 8220955 RED; normal ALTER and committed-bundle compensation controls GREEN; PR/review/history excluded from discovery; exact-root issue dedup only after RED.');
